<?php
require_once __DIR__.'/config/database.php';$id=(int)($_GET['id']??0);
$s=$pdo->prepare("SELECT t.*,u.username FROM threads t JOIN users u ON u.id=t.user_id WHERE t.id=?");$s->execute([$id]);$thread=$s->fetch();if(!$thread)exit('Hilo no encontrado');
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_SESSION['user_id'])){$s=$pdo->prepare("INSERT INTO posts(thread_id,user_id,content) VALUES(?,?,?)");$s->execute([$id,$_SESSION['user_id'],trim($_POST['content'])]);$pdo->prepare("UPDATE threads SET last_activity=NOW() WHERE id=?")->execute([$id]);header("Location:thread.php?id=$id");exit;}
$s=$pdo->prepare("SELECT p.*,u.username FROM posts p JOIN users u ON u.id=p.user_id WHERE thread_id=? ORDER BY p.created_at ASC");$s->execute([$id]);$posts=$s->fetchAll();
?><!DOCTYPE html><html lang="es"><head><?php include __DIR__.'/partials/head.php';?></head><body><?php include __DIR__.'/partials/nav.php';?><main class="container"><article class="thread-main"><p class="eyebrow">FORO / HILO</p><h1><?=htmlspecialchars($thread['title'])?></h1><div class="post original"><b><?=htmlspecialchars($thread['username'])?></b><span class="muted"><?=htmlspecialchars($thread['created_at'])?></span><p><?=nl2br(htmlspecialchars($thread['content']))?></p></div><?php foreach($posts as $p):?><div class="post"><b><?=htmlspecialchars($p['username'])?></b><span class="muted"><?=htmlspecialchars($p['created_at'])?></span><p><?=nl2br(htmlspecialchars($p['content']))?></p></div><?php endforeach;?></article><?php if(isset($_SESSION['user_id'])):?><form class="thread-form" method="post"><textarea name="content" maxlength="2000" placeholder="Responder..." required></textarea><button class="btn">Responder</button></form><?php endif;?></main></body></html>